package com.enterprise.siem.agent;
import com.enterprise.siem.security.TlsContextFactory; import com.enterprise.siem.security.TlsConfiguration; import java.io.*; import java.net.*; import java.nio.charset.StandardCharsets; import java.time.Duration; import javax.net.ssl.SSLSocket;
public final class SIEMClient implements AutoCloseable { private final String host; private final int port; private final int maxLine; private Socket socket; private BufferedWriter out; public SIEMClient(String host,int port){this(host,port,65536);} public SIEMClient(String host,int port,int maxLine){this.host=host;this.port=port;this.maxLine=maxLine;}
 public SIEMClient(String host,int port,int maxLine,TlsConfiguration tls){this.host=host;this.port=port;this.maxLine=maxLine;this.tls=tls==null?TlsConfiguration.disabled():tls;}
 private TlsConfiguration tls=TlsConfiguration.disabled();
 public synchronized void send(String json) throws IOException { if(json==null||json.getBytes(StandardCharsets.UTF_8).length>maxLine)throw new IOException("event too large"); IOException failure=null; for(int attempt=0;attempt<4;attempt++){try{connect();out.write(json);out.newLine();out.flush();return;}catch(IOException e){failure=e;close();try{Thread.sleep(Duration.ofMillis(100L*(1L<<attempt)));}catch(InterruptedException x){Thread.currentThread().interrupt();break;}}}throw failure==null?new IOException("connection failed"):failure; }
 private void connect() throws IOException {if(socket==null||socket.isClosed()){try {if(tls.enabled()){var factory=TlsContextFactory.create(tls).getSocketFactory();socket=factory.createSocket(host,port);var ssl=(SSLSocket)socket;var parameters=ssl.getSSLParameters();parameters.setEndpointIdentificationAlgorithm("HTTPS");ssl.setSSLParameters(parameters);ssl.startHandshake();}else{socket=new Socket();socket.connect(new InetSocketAddress(host,port),3000);}} catch(Exception exception){throw new IOException("TLS connection failed",exception);} socket.setSoTimeout(5000);out=new BufferedWriter(new OutputStreamWriter(socket.getOutputStream(),StandardCharsets.UTF_8));}} public void close(){try{if(socket!=null)socket.close();}catch(IOException ignored){}}
}
